package com.gefavorites;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class FavoritesStore
{
    private static final String LISTS_KEY = "lists";
    private static final String ACTIVE_KEY = "activeList";
    private static final String LEGACY_KEY = "favorites";
    private static final String DEFAULT_LIST = "Favorites";

    private final ConfigManager configManager;
    private final Map<String, LinkedHashSet<Integer>> lists = new LinkedHashMap<>();
    private String activeList = DEFAULT_LIST;

    @Inject
    FavoritesStore(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    public synchronized void load()
    {
        lists.clear();
        String names = configManager.getConfiguration(GeFavoritesConfig.GROUP, LISTS_KEY);
        if (names != null && !names.trim().isEmpty())
        {
            for (String encoded : names.split(","))
            {
                String name = decode(encoded.trim());
                if (!name.isEmpty())
                {
                    lists.put(name, readIds("list." + encoded.trim()));
                }
            }
        }

        if (lists.isEmpty())
        {
            LinkedHashSet<Integer> migrated = readIds(LEGACY_KEY);
            lists.put(DEFAULT_LIST, migrated);
        }

        String savedActive = configManager.getConfiguration(GeFavoritesConfig.GROUP, ACTIVE_KEY);
        activeList = savedActive != null && lists.containsKey(savedActive) ? savedActive : lists.keySet().iterator().next();
        saveAll();
    }

    public synchronized List<String> listNames()
    {
        return Collections.unmodifiableList(new ArrayList<>(lists.keySet()));
    }

    public synchronized String activeList()
    {
        return activeList;
    }

    public synchronized void setActiveList(String name)
    {
        if (lists.containsKey(name))
        {
            activeList = name;
            configManager.setConfiguration(GeFavoritesConfig.GROUP, ACTIVE_KEY, activeList);
        }
    }

    public synchronized boolean createList(String requestedName)
    {
        String name = requestedName == null ? "" : requestedName.trim();
        if (name.isEmpty() || lists.containsKey(name))
        {
            return false;
        }
        lists.put(name, new LinkedHashSet<>());
        activeList = name;
        saveAll();
        return true;
    }

    public synchronized boolean deleteList(String name)
    {
        if (!lists.containsKey(name) || lists.size() <= 1)
        {
            return false;
        }
        lists.remove(name);
        if (name.equals(activeList))
        {
            activeList = lists.keySet().iterator().next();
        }
        saveAll();
        return true;
    }

    public synchronized boolean addToActive(int itemId)
    {
        boolean changed = lists.get(activeList).add(itemId);
        if (changed)
        {
            saveList(activeList);
        }
        return changed;
    }

    public synchronized boolean remove(String listName, int itemId)
    {
        Set<Integer> ids = lists.get(listName);
        boolean changed = ids != null && ids.remove(itemId);
        if (changed)
        {
            saveList(listName);
        }
        return changed;
    }

    public synchronized boolean containsInActive(int itemId)
    {
        return lists.get(activeList).contains(itemId);
    }

    public synchronized List<Integer> activeItems()
    {
        return items(activeList);
    }

    public synchronized List<Integer> items(String listName)
    {
        Set<Integer> ids = lists.get(listName);
        return ids == null
            ? Collections.emptyList()
            : Collections.unmodifiableList(new ArrayList<>(ids));
    }

    private LinkedHashSet<Integer> readIds(String key)
    {
        LinkedHashSet<Integer> result = new LinkedHashSet<>();
        String raw = configManager.getConfiguration(GeFavoritesConfig.GROUP, key);
        if (raw == null || raw.trim().isEmpty())
        {
            return result;
        }
        for (String token : raw.split(","))
        {
            try
            {
                result.add(Integer.parseInt(token.trim()));
            }
            catch (NumberFormatException ignored)
            {
                // Skip damaged entries without sacrificing the rest of the list.
            }
        }
        return result;
    }

    private void saveAll()
    {
        StringBuilder names = new StringBuilder();
        for (String name : lists.keySet())
        {
            String encoded = encode(name);
            if (names.length() > 0)
            {
                names.append(',');
            }
            names.append(encoded);
            saveList(name);
        }
        configManager.setConfiguration(GeFavoritesConfig.GROUP, LISTS_KEY, names.toString());
        configManager.setConfiguration(GeFavoritesConfig.GROUP, ACTIVE_KEY, activeList);
    }

    private void saveList(String name)
    {
        StringBuilder value = new StringBuilder();
        for (int itemId : lists.get(name))
        {
            if (value.length() > 0)
            {
                value.append(',');
            }
            value.append(itemId);
        }
        configManager.setConfiguration(GeFavoritesConfig.GROUP, "list." + encode(name), value.toString());
    }

    private static String encode(String value)
    {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(value.getBytes(StandardCharsets.UTF_8));
    }

    private static String decode(String value)
    {
        try
        {
            return new String(Base64.getUrlDecoder().decode(value), StandardCharsets.UTF_8);
        }
        catch (IllegalArgumentException ex)
        {
            return "";
        }
    }
}

