package com.gefavorites;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Rectangle;
import java.awt.event.ActionEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.http.api.item.ItemPrice;

public class GeFavoritesPanel extends PluginPanel
{
    private static final int ROW_HEIGHT = 34;

    private final FavoritesStore store;
    private final ItemManager itemManager;
    private final ClientThread clientThread;
    private final Consumer<String> activateListInGe;
    private final Consumer<Integer> showSingleItem;
    private final Runnable favoritesChanged;

    private final JPanel content = new WidthTrackingPanel();
    private final JPanel searchResults = new JPanel();
    private final JTextField searchField = new JTextField();
    private final Map<String, Boolean> collapsedLists = new HashMap<>();

    public GeFavoritesPanel(
        FavoritesStore store,
        ItemManager itemManager,
        ClientThread clientThread,
        Consumer<String> activateListInGe,
        Consumer<Integer> showSingleItem,
        Runnable favoritesChanged)
    {
        super(false);
        this.store = store;
        this.itemManager = itemManager;
        this.clientThread = clientThread;
        this.activateListInGe = activateListInGe;
        this.showSingleItem = showSingleItem;
        this.favoritesChanged = favoritesChanged;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(6, 4, 6, 4));

        add(buildHeader(), BorderLayout.NORTH);

        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);
        content.setAlignmentX(Component.LEFT_ALIGNMENT);

        searchResults.setLayout(new BoxLayout(searchResults, BoxLayout.Y_AXIS));
        searchResults.setBackground(ColorScheme.DARK_GRAY_COLOR);
        searchResults.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.add(searchResults);

        JScrollPane scrollPane = new JScrollPane(content);
        scrollPane.setBorder(null);
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        add(scrollPane, BorderLayout.CENTER);

        rebuildLists();
    }

    private JPanel buildHeader()
    {
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));

        JPanel titleRow = new JPanel(new BorderLayout(4, 0));
        titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        JPanel titleCopy = new JPanel();
        titleCopy.setOpaque(false);
        titleCopy.setLayout(new BoxLayout(titleCopy, BoxLayout.Y_AXIS));
        JLabel title = new JLabel("GE Favorites");
        title.setForeground(ColorScheme.BRAND_ORANGE);
        JLabel subtitle = new JLabel("Select a list, then click ★ in the GE");
        subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        titleCopy.add(title);
        titleCopy.add(subtitle);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));
        titleRow.add(titleCopy, BorderLayout.CENTER);

        JButton newList = compactButton("+ List", 54);
        newList.addActionListener(e -> createList());
        titleRow.add(newList, BorderLayout.EAST);
        header.add(titleRow);
        header.add(Box.createRigidArea(new Dimension(0, 6)));

        JPanel searchRow = new JPanel(new BorderLayout(4, 0));
        searchRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        searchRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        searchField.setToolTipText("Search tradeable items to add");
        searchField.addActionListener(this::search);
        searchRow.add(searchField, BorderLayout.CENTER);

        JButton searchButton = compactButton("Search", 58);
        searchButton.addActionListener(this::search);
        searchRow.add(searchButton, BorderLayout.EAST);
        header.add(searchRow);

        return header;
    }

    private void createList()
    {
        String name = JOptionPane.showInputDialog(this, "List name", "Create GE favorite list", JOptionPane.PLAIN_MESSAGE);
        if (store.createList(name))
        {
            searchResults.removeAll();
            rebuildLists();
            favoritesChanged.run();
        }
    }

    private void search(ActionEvent ignored)
    {
        String query = searchField.getText().trim();
        searchResults.removeAll();

        if (!query.isEmpty())
        {
            JLabel heading = new JLabel("Add to " + store.activeList());
            heading.setBorder(BorderFactory.createEmptyBorder(2, 4, 4, 0));
            heading.setAlignmentX(Component.LEFT_ALIGNMENT);
            searchResults.add(heading);

            List<ItemPrice> results = itemManager.search(query).stream()
                .filter(item -> !store.containsInActive(item.getId()))
                .sorted(Comparator.comparing(ItemPrice::getName))
                .limit(10)
                .collect(Collectors.toList());

            for (ItemPrice item : results)
            {
                JButton add = new JButton("+  " + item.getName());
                add.setHorizontalAlignment(SwingConstants.LEFT);
                add.setAlignmentX(Component.LEFT_ALIGNMENT);
                add.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
                add.addActionListener(e ->
                {
                    store.addToActive(item.getId());
                    searchField.setText("");
                    searchResults.removeAll();
                    rebuildLists();
                    favoritesChanged.run();
                });
                searchResults.add(add);
                searchResults.add(Box.createRigidArea(new Dimension(0, 2)));
            }
            searchResults.add(Box.createRigidArea(new Dimension(0, 6)));
        }

        refresh();
    }

    public void rebuildLists()
    {
        while (content.getComponentCount() > 1)
        {
            content.remove(1);
        }

        for (String listName : store.listNames())
        {
            content.add(createListSection(listName));
            content.add(Box.createRigidArea(new Dimension(0, 4)));
        }

        refresh();
    }

    private JPanel createListSection(String listName)
    {
        boolean selected = listName.equals(store.activeList());
        boolean collapsed = collapsedLists.getOrDefault(listName, false);
        List<Integer> items = store.items(listName);

        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(ColorScheme.DARK_GRAY_COLOR);
        section.setAlignmentX(Component.LEFT_ALIGNMENT);
        int bodyHeight = collapsed ? 0 : (items.isEmpty() ? 28 : items.size() * ROW_HEIGHT);
        int sectionHeight = 26 + bodyHeight;
        section.setMaximumSize(new Dimension(Integer.MAX_VALUE, sectionHeight));
        section.setMinimumSize(new Dimension(0, sectionHeight));

        JPanel header = new JPanel(new BorderLayout(4, 0));
        header.setBackground(selected ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(BorderFactory.createEmptyBorder(2, 3, 2, 4));
        header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        header.setMinimumSize(new Dimension(0, 28));
        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        JLabel title = new JLabel((collapsed ? "▸  " : "▾  ") + listName + "  ·  " + items.size());
        if (selected)
        {
            title.setForeground(ColorScheme.BRAND_ORANGE);
            title.setToolTipText("Active GE favorites list");
        }
        header.add(title, BorderLayout.CENTER);

        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        actions.setOpaque(false);

        JButton activate = compactButton(selected ? "★" : "☆", 26);
        activate.setToolTipText(selected ? "Active GE list" : "Use this list in the GE");
        activate.addActionListener(e ->
        {
            store.setActiveList(listName);
            rebuildLists();
            activateListInGe.accept(listName);
        });
        actions.add(activate);

        JButton delete = compactButton("×", 24);
        delete.setToolTipText("Delete this list");
        delete.setEnabled(store.listNames().size() > 1);
        delete.addActionListener(e ->
        {
            if (store.deleteList(listName))
            {
                collapsedLists.remove(listName);
                rebuildLists();
                favoritesChanged.run();
            }
        });
        actions.add(delete);
        header.add(actions, BorderLayout.EAST);

        MouseAdapter toggleListener = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                store.setActiveList(listName);
                collapsedLists.put(listName, !collapsedLists.getOrDefault(listName, false));
                rebuildLists();
            }
        };
        header.addMouseListener(toggleListener);
        title.addMouseListener(toggleListener);
        section.add(header);

        if (!collapsed)
        {
            if (items.isEmpty())
            {
                JLabel empty = new JLabel("No saved items");
                empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                empty.setBorder(BorderFactory.createEmptyBorder(7, 28, 7, 0));
                empty.setAlignmentX(Component.LEFT_ALIGNMENT);
                section.add(empty);
            }
            else
            {
                for (int itemId : items)
                {
                    section.add(createItemRow(listName, itemId));
                }
            }
        }

        return section;
    }

    private JPanel createItemRow(String listName, int itemId)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
        row.setMinimumSize(new Dimension(0, ROW_HEIGHT));
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        JLabel icon = new JLabel();
        icon.setHorizontalAlignment(SwingConstants.LEFT);
        icon.setPreferredSize(new Dimension(30, 32));
        icon.setMinimumSize(new Dimension(30, 32));
        icon.setMaximumSize(new Dimension(30, 32));
        row.add(icon, BorderLayout.WEST);

        JLabel name = new JLabel("Item " + itemId);
        name.setToolTipText("Click to show this item in the GE");
        row.add(name, BorderLayout.CENTER);

        JButton remove = compactButton("×", 20);
        remove.setFocusable(false);
        remove.setToolTipText("Remove from " + listName);
        remove.addActionListener(e ->
        {
            store.remove(listName, itemId);
            rebuildLists();
            favoritesChanged.run();
        });
        row.add(remove, BorderLayout.EAST);

        MouseAdapter openInGe = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                store.setActiveList(listName);
                showSingleItem.accept(itemId);
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                row.setBackground(ColorScheme.DARK_GRAY_COLOR);
            }
        };
        row.addMouseListener(openInGe);
        icon.addMouseListener(openInGe);
        name.addMouseListener(openInGe);

        clientThread.invoke(() ->
        {
            String resolvedName;
            AsyncBufferedImage resolvedImage = null;
            try
            {
                resolvedName = itemManager.getItemComposition(itemId).getName();
                resolvedImage = itemManager.getImage(itemId);
            }
            catch (RuntimeException ex)
            {
                resolvedName = "Item " + itemId;
            }

            final String finalName = resolvedName;
            final AsyncBufferedImage finalImage = resolvedImage;
            SwingUtilities.invokeLater(() ->
            {
                name.setText(finalName);
                name.setToolTipText(finalName + " | Click to show in GE");
                if (finalImage != null)
                {
                    finalImage.addTo(icon);
                }
            });
        });

        return row;
    }

    /** Makes BoxLayout children consume the sidebar viewport width. Without this,
     * the item name's preferred width can push the remove button off-screen. */
    private static final class WidthTrackingPanel extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return Math.max(16, visibleRect.height - 16);
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }

    private static JButton compactButton(String text, int width)
    {
        JButton button = new JButton(text);
        button.setMargin(new java.awt.Insets(0, 2, 0, 2));
        button.setPreferredSize(new Dimension(width, 22));
        button.setMinimumSize(new Dimension(width, 22));
        button.setMaximumSize(new Dimension(width, 22));
        return button;
    }

    private void refresh()
    {
        SwingUtilities.invokeLater(() ->
        {
            content.revalidate();
            content.repaint();
        });
    }
}

package com.gefavorites;

