import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
    name = "GE Favorites",
    description = "Save frequently purchased Grand Exchange items and pick them from the GE search bar",
    tags = {"grand exchange", "ge", "favorites", "items"}
)
@Slf4j
public class GeFavoritesPlugin extends Plugin
{
    private static final int MAX_GE_RESULTS = 250;

    // These are the same small square button sprites used by established GE
    // filter plugins. The selected sprite gives the red active state.
    private static final int BUTTON_SPRITE = 195;
    private static final int BUTTON_SPRITE_SELECTED = 196;
    private static final int STAR_SPRITE = 1130;
    private static final int BUTTON_SIZE = 20;
    private static final int ICON_SIZE = 14;
    private static final int GE_SEARCH_MODE = 14;
    private static final int KEY_PRESS_SCRIPT_ID = 905;

    private static final String SEARCH_TOKEN = "ge-favorites-list";
    private static final String BUTTON_WIDGET_NAME = "ge favorites";
    private static final String QUEST_HELPER_WIDGET_NAME = "quest helper";
    private static final String ACTION_ENABLE = "View active GE favorites";
    private static final String ACTION_DISABLE = "Clear GE favorites filter";
    private static final String ACTION_EMPTY = "Active GE favorites list is empty";

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ConfigManager configManager;
    @Inject private ItemManager itemManager;
    @Inject private FavoritesStore store;

    private GeFavoritesPanel panel;
    private NavigationButton navigationButton;

    private boolean grandExchangeOpen;
    private boolean geFilterUiRunning;
    private boolean filterEnabled;
    private Integer selectedFavoriteId;
    private String previousSearchText = "";

    private Widget containerWidget;
    private Widget searchBoxWidget;
    private Widget titleWidget;
    private Widget backgroundWidget;
    private Widget iconWidget;

    @Provides
    GeFavoritesConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(GeFavoritesConfig.class);
    }

    @Override
    protected void startUp()
    {
        resetGeState();
        store.load();

        try
        {
            if (SwingUtilities.isEventDispatchThread())
            {
                createSidebar();
            }
            else
            {
                SwingUtilities.invokeAndWait(this::createSidebar);
            }
        }
        catch (Exception ex)
        {
            log.error("Unable to create GE Favorites sidebar", ex);
            throw new RuntimeException("Unable to create GE Favorites sidebar", ex);
        }

        clientThread.invoke(this::tryStartGeFilterUi);
    }

    @Override
    protected void shutDown()
    {
        clientThread.invoke(this::stopGeFilterUi);

        Runnable removeSidebar = () ->
        {
            if (navigationButton != null)
            {
                clientToolbar.removeNavigation(navigationButton);
            }
            panel = null;
            navigationButton = null;
        };

        if (SwingUtilities.isEventDispatchThread())
        {
            removeSidebar.run();
        }
        else
        {
            SwingUtilities.invokeLater(removeSidebar);
        }
    }

    private void createSidebar()
    {
        panel = new GeFavoritesPanel(
            store,
            itemManager,
            clientThread,
            this::activateListInGe,
            this::showSingleFavoriteInGe,
            this::favoritesChanged);

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/gefavorites/icon.png");
        if (icon == null)
        {
            icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        }

        navigationButton = NavigationButton.builder()
            .tooltip("GE Favorites")
            .icon(icon)
            .priority(7)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);
    }

    private void resetGeState()
    {
        grandExchangeOpen = false;
        geFilterUiRunning = false;
        filterEnabled = false;
        selectedFavoriteId = null;
        previousSearchText = "";
        containerWidget = null;
        searchBoxWidget = null;
        titleWidget = null;
        backgroundWidget = null;
        iconWidget = null;
    }

    private void activateListInGe(String listName)
    {
        store.setActiveList(listName);
        selectedFavoriteId = null;

        clientThread.invoke(() ->
        {
            updateFilterWidgets();
            if (filterEnabled)
            {
                showActiveFavorites();
            }
        });
    }

    private void showSingleFavoriteInGe(int itemId)
    {
        selectedFavoriteId = itemId;
        clientThread.invoke(() ->
        {
            if (!isSearchVisible())
            {
                return;
            }

            startGeFilterUi();
            enableFilter();
        });
    }

    private void favoritesChanged()
    {
        clientThread.invoke(() ->
        {
            updateFilterWidgets();
            if (filterEnabled)
            {
                showActiveFavorites();
            }
        });
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.GE_OFFERS)
        {
            grandExchangeOpen = true;
            clientThread.invoke(this::tryStartGeFilterUi);
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() == InterfaceID.GE_OFFERS)
        {
            grandExchangeOpen = false;
            clientThread.invoke(this::stopGeFilterUi);
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (event.getScriptId() == ScriptID.MESSAGE_LAYER_CLOSE)
        {
            clientThread.invoke(this::stopGeFilterUi);
            return;
        }

        if (event.getScriptId() == ScriptID.GE_ITEM_SEARCH
            || event.getScriptId() == ScriptID.CHAT_TEXT_INPUT_REBUILD)
        {
            clientThread.invokeLater(this::tryStartGeFilterUi);
        }
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (!grandExchangeOpen && client.getWidget(InterfaceID.GE_OFFERS, 0) != null)
        {
            grandExchangeOpen = true;
        }

        if (isSearchVisible())
        {
            tryStartGeFilterUi();
            positionFilterButton();
        }
        else if (geFilterUiRunning)
        {
            stopGeFilterUi();
        }
    }

    @Subscribe(priority = 100)
    public void onGrandExchangeSearched(GrandExchangeSearched event)
    {
        if (!filterEnabled || event.isConsumed())
        {
            return;
        }

        String input = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
        if (!SEARCH_TOKEN.equals(input))
        {
            return;
        }

        event.consume();
        setFavoriteSearchResults();
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!geFilterUiRunning)
        {
            return;
        }

        Widget widget = event.getWidget();
        if (widget != backgroundWidget && widget != iconWidget)
        {
            return;
        }

        String option = event.getMenuOption();
        if (ACTION_DISABLE.equals(option))
        {
            disableFilter(true);
        }
        else if (ACTION_ENABLE.equals(option))
        {
            if (!store.activeItems().isEmpty())
            {
                selectedFavoriteId = null;
                enableFilter();
            }
        }
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired event)
    {
        if (!filterEnabled || event.getScriptId() != KEY_PRESS_SCRIPT_ID || !isItemSearchInput())
        {
            return;
        }

        ScriptEvent scriptEvent = event.getScriptEvent();
        if (scriptEvent == null || scriptEvent.getTypedKeyChar() == 0)
        {
            return;
        }

        String character = Character.toString((char) scriptEvent.getTypedKeyChar());
        filterEnabled = false;
        selectedFavoriteId = null;
        updateFilterWidgets();
        searchGe(character, false);
    }

    private void tryStartGeFilterUi()
    {
        if (!grandExchangeOpen && client.getWidget(InterfaceID.GE_OFFERS, 0) != null)
        {
            grandExchangeOpen = true;
        }

        if (!isSearchVisible())
        {
            return;
        }

        if (!geFilterUiRunning || widgetsDetached())
        {
            startGeFilterUi();
        }
        else
        {
            positionFilterButton();
            updateFilterWidgets();
        }
    }

    private void startGeFilterUi()
    {
        containerWidget = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
        searchBoxWidget = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
        if (containerWidget == null || searchBoxWidget == null)
        {
            return;
        }

        hideFilterWidgets();

        titleWidget = createTitleWidget();
        backgroundWidget = createGraphicWidget(BUTTON_SPRITE, BUTTON_SIZE, BUTTON_SIZE, 0, 0);
        iconWidget = createGraphicWidget(STAR_SPRITE, ICON_SIZE, ICON_SIZE, 3, 3);

        geFilterUiRunning = backgroundWidget != null && iconWidget != null;
        if (!geFilterUiRunning)
        {
            return;
        }

        positionFilterButton();
        updateFilterWidgets();

        if (filterEnabled)
        {
            showActiveFavorites();
        }
    }

    private void stopGeFilterUi()
    {
        filterEnabled = false;
        selectedFavoriteId = null;
        geFilterUiRunning = false;

        hideFilterWidgets();
        containerWidget = null;
        searchBoxWidget = null;
        titleWidget = null;
        backgroundWidget = null;
        iconWidget = null;
    }

    private void enableFilter()
    {
        if (!isSearchVisible())
        {
            return;
        }

        if (selectedFavoriteId == null && store.activeItems().isEmpty())
        {
            updateFilterWidgets();
            return;
        }

        startGeFilterUiIfNeeded();
        if (!geFilterUiRunning)
        {
            return;
        }

        if (!filterEnabled)
        {
            previousSearchText = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
        }

        filterEnabled = true;
        showActiveFavorites();
    }

    private void showActiveFavorites()
    {
        if (!filterEnabled || searchBoxWidget == null)
        {
            return;
        }

        searchGe(SEARCH_TOKEN, true);
        updateFilterWidgets();
    }

    private void disableFilter(boolean restoreSearch)
    {
        if (!filterEnabled)
        {
            updateFilterWidgets();
            return;
        }

        filterEnabled = false;
        selectedFavoriteId = null;
        String search = restoreSearch ? previousSearchText : "";
        searchGe(search == null ? "" : search, false);
        updateFilterWidgets();
    }

    private void searchGe(String searchTerm, boolean hideSearchBox)
    {
        client.setVarcStrValue(VarClientID.MESLAYERINPUT, searchTerm);
        client.setVarcIntValue(VarClientID.MESLAYERMODE, GE_SEARCH_MODE);
        forceUpdateSearch(hideSearchBox);
    }

    private void forceUpdateSearch(boolean hideSearchBox)
    {
        clientThread.invokeLater(() ->
        {
            searchBoxWidget = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
            if (searchBoxWidget == null)
            {
                return;
            }

            Object[] scriptArgs = searchBoxWidget.getOnKeyListener();
            if (scriptArgs == null)
            {
                log.warn("GE Favorites could not refresh: GE search input has no key listener");
                return;
            }

            client.runScript(scriptArgs);
            searchBoxWidget.setHidden(hideSearchBox);
            updateFilterWidgets();
        });
    }

    private void setFavoriteSearchResults()
    {
        List<Integer> items;
        if (selectedFavoriteId != null && store.containsInActive(selectedFavoriteId))
        {
            items = Collections.singletonList(selectedFavoriteId);
        }
        else
        {
            selectedFavoriteId = null;
            items = store.activeItems();
        }

        int count = Math.min(items.size(), MAX_GE_RESULTS);
        short[] resultIds = new short[count];
        for (int i = 0; i < count; i++)
        {
            resultIds[i] = (short) (items.get(i) & 0xFFFF);
        }

        client.setGeSearchResultIndex(0);
        client.setGeSearchResultCount(resultIds.length);
        client.setGeSearchResultIds(resultIds);
    }

    private void updateFilterWidgets()
    {
        if (!geFilterUiRunning)
        {
            return;
        }

        boolean hasItems = selectedFavoriteId != null || !store.activeItems().isEmpty();
        String action = filterEnabled ? ACTION_DISABLE : hasItems ? ACTION_ENABLE : ACTION_EMPTY;

        setWidgetAction(backgroundWidget, action);
        setWidgetAction(iconWidget, action);

        if (backgroundWidget != null)
        {
            backgroundWidget.setSpriteId(filterEnabled ? BUTTON_SPRITE_SELECTED : BUTTON_SPRITE);
            backgroundWidget.revalidate();
        }

        if (titleWidget != null)
        {
            String label = selectedFavoriteId == null
                ? store.activeList() + " (" + store.activeItems().size() + ")"
                : "Selected favorite";
            titleWidget.setText("<col=ff981f>GE Favorites</col>  ·  " + label);
            titleWidget.setHidden(!filterEnabled);
            titleWidget.revalidate();
        }

        if (searchBoxWidget != null)
        {
            searchBoxWidget.setHidden(filterEnabled);
        }
    }

    private void setWidgetAction(Widget widget, String action)
    {
        if (widget == null)
        {
            return;
        }

        widget.setAction(0, action);
        widget.setName(BUTTON_WIDGET_NAME);
        widget.setHidden(false);
        widget.revalidate();
    }

    private Widget createGraphicWidget(int spriteId, int width, int height, int x, int y)
    {
        if (containerWidget == null)
        {
            return null;
        }

        Widget widget = containerWidget.createChild(-1, WidgetType.GRAPHIC);
        widget.setOriginalX(x);
        widget.setOriginalY(y);
        widget.setOriginalWidth(width);
        widget.setOriginalHeight(height);
        widget.setSpriteId(spriteId);
        widget.setName(BUTTON_WIDGET_NAME);
        widget.setOnOpListener((JavaScriptCallback) e -> { });
        widget.setHasListener(true);
        widget.revalidate();
        return widget;
    }

    private Widget createTitleWidget()
    {
        if (containerWidget == null || searchBoxWidget == null)
        {
            return null;
        }

        Widget widget = containerWidget.createChild(-1, WidgetType.TEXT);
        widget.setOriginalWidth(searchBoxWidget.getWidth());
        widget.setOriginalHeight(searchBoxWidget.getHeight());
        widget.setOriginalX(0);
        widget.setOriginalY(0);
        widget.setTextShadowed(false);
        widget.setXTextAlignment(1);
        widget.setYTextAlignment(1);
        widget.setFontId(FontID.BOLD_12);
        widget.setTextColor(0xFFFFFF);
        widget.setHidden(true);
        widget.revalidate();
        return widget;
    }

    private void positionFilterButton()
    {
        if (!geFilterUiRunning || containerWidget == null || backgroundWidget == null || iconWidget == null)
        {
            return;
        }

        int containerWidth = containerWidget.getWidth();
        if (containerWidth <= 0)
        {
            containerWidth = containerWidget.getOriginalWidth();
        }
        if (containerWidth <= 0)
        {
            return;
        }

        int x = Math.max(0, containerWidth - BUTTON_SIZE);
        Widget questHelperButton = findQuestHelperButton();
        if (questHelperButton != null)
        {
            int questX = questHelperButton.getOriginalX();
            if (questX > 0)
            {
                x = Math.max(0, questX - BUTTON_SIZE - 2);
            }
        }

        backgroundWidget.setOriginalX(x);
        backgroundWidget.setOriginalY(0);
        backgroundWidget.setOriginalWidth(BUTTON_SIZE);
        backgroundWidget.setOriginalHeight(BUTTON_SIZE);
        backgroundWidget.setHidden(false);
        backgroundWidget.revalidate();

        iconWidget.setOriginalX(x + 3);
        iconWidget.setOriginalY(3);
        iconWidget.setOriginalWidth(ICON_SIZE);
        iconWidget.setOriginalHeight(ICON_SIZE);
        iconWidget.setHidden(false);
        iconWidget.revalidate();
    }

    private Widget findQuestHelperButton()
    {
        if (containerWidget == null)
        {
            return null;
        }

        Widget[] children = containerWidget.getChildren();
        if (children == null)
        {
            return null;
        }

        for (Widget child : children)
        {
            if (child != null && QUEST_HELPER_WIDGET_NAME.equals(child.getName()))
            {
                return child;
            }
        }
        return null;
    }

    private boolean widgetsDetached()
    {
        return containerWidget == null
            || backgroundWidget == null
            || iconWidget == null
            || backgroundWidget.getParent() == null
            || iconWidget.getParent() == null;
    }

    private boolean isSearchVisible()
    {
        if (!grandExchangeOpen)
        {
            return false;
        }

        Widget container = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
        if (container == null || container.isHidden())
        {
            return false;
        }

        return client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS) != null;
    }

    private boolean isItemSearchInput()
    {
        if (!isSearchVisible())
        {
            return false;
        }

        Widget title = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
        return title != null && title.isHidden();
    }

    private void startGeFilterUiIfNeeded()
    {
        if (!geFilterUiRunning || widgetsDetached())
        {
            startGeFilterUi();
        }
    }

    private void hideFilterWidgets()
    {
        hideWidget(titleWidget);
        hideWidget(backgroundWidget);
        hideWidget(iconWidget);
    }

    private static void hideWidget(Widget widget)
    {
        if (widget != null)
        {
            widget.setHidden(true);
        }
    }
}

